import numpy as np
from scipy.optimize import minimize, brentq

# Parameters
vocab_size = 150000
target_kl = 10.0
tolerance = 0.001

# Uniform distribution
U = 1.0 / vocab_size

def kl_forward(P):
    """KL(P||U) = Σ P(i) * log(P(i) / U(i))"""
    mask = P > 0
    return np.sum(P[mask] * np.log(P[mask] / U))

def kl_backward(P):
    """KL(U||P) = Σ U(i) * log(U(i) / P(i))"""
    return np.sum(U * np.log(U / P))

# Strategy: Use a distribution with k tokens having probability p_high
# and the remaining tokens having probability p_low
# k * p_high + (n-k) * p_low = 1

def find_distribution_with_k_groups():
    """
    Use k high-probability tokens and (n-k) low-probability tokens
    """
    n = vocab_size

    # For a given k, find p_high such that backward KL = 10
    # Then check what forward KL is

    for k in [2, 3, 5, 10, 20, 50, 100, 200, 500, 1000]:
        def backward_kl_for_k(p_high):
            if p_high <= 0 or p_high >= 1:
                return float('inf')
            p_low = (1 - k * p_high) / (n - k)
            if p_low <= 0:
                return float('inf')

            # KL(U||P) = k*(1/n)*log(1/(n*p_high)) + (n-k)*(1/n)*log(1/(n*p_low))
            kl_b = (k/n) * np.log(1/(n * p_high)) + ((n-k)/n) * np.log(1/(n * p_low))
            return kl_b

        def forward_kl_for_k(p_high):
            if p_high <= 0 or p_high >= 1:
                return float('inf')
            p_low = (1 - k * p_high) / (n - k)
            if p_low <= 0:
                return float('inf')

            # KL(P||U) = k*p_high*log(p_high/U) + (n-k)*p_low*log(p_low/U)
            kl_f = k * p_high * np.log(p_high / U) + (n-k) * p_low * np.log(p_low / U)
            return kl_f

        # Find p_high that gives backward KL = 10
        # p_high must be < 1/k for p_low to be positive

        p_high_max = 1.0 / k - 1e-10

        # Check backward KL at different p_high values
        print(f"\n=== k={k} ===")
        for p_high in [0.5/k, 0.8/k, 0.9/k, 0.99/k, 0.999/k, 0.9999/k, 0.99999/k]:
            try:
                kl_b = backward_kl_for_k(p_high)
                kl_f = forward_kl_for_k(p_high)
                print(f"p_high={p_high:.10f}: backward KL={kl_b:.4f}, forward KL={kl_f:.4f}")
            except Exception as e:
                print(f"p_high={p_high:.10f}: error - {e}")

    return None

find_distribution_with_k_groups()
